begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(26);
insert into auth.users(id,email) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','complete-a@example.invalid'),('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','complete-b@example.invalid');
insert into public.rundown_versions(id,title,area,summary,stops,published)
select '91111111-1111-4111-8111-111111111111','Synthetic Search A','CompleteTest','completion query',stops,true from public.rundown_versions where id='11111111-1111-4111-8111-111111111111';
insert into public.rundown_versions(id,title,area,summary,stops,published)
select '91111111-1111-4111-8111-111111111112','Synthetic Search B','CompleteTest','completion query',stops,true from public.rundown_versions where id='11111111-1111-4111-8111-111111111111';
set local role anon;
select is(jsonb_array_length(public.search_rundowns('completion','completetest',1)->'items'),1,'Discovery limit is bounded');
select set_config('c67.search_cursor',public.search_rundowns('completion','completetest',1)->>'next_cursor',true);
select is(public.search_rundowns('completion','completetest',1,current_setting('c67.search_cursor'))->'items'->0->>'id','91111111-1111-4111-8111-111111111111','Discovery cursor has no gap');
select throws_ok($$select public.search_rundowns('other','completetest',1,current_setting('c67.search_cursor'))$$,'PT400','Invalid discovery cursor','Filter change invalidates cursor');
select throws_ok($$select public.search_rundowns('',null,51)$$,'PT400','Invalid discovery filters or limit','Oversize page rejected');
select throws_ok($$select public.claim_journal_job()$$,'42501','permission denied for function claim_journal_job','Anonymous worker call denied');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',true);
select set_config('c67.original',public.create_trip_v3('91111111-1111-4111-8111-111111111111','2026-11-01T02:00Z','UTC','unspecified','51111111-1111-4111-8111-111111111111')::text,true);
select set_config('c67.trip',current_setting('c67.original')::jsonb->>'id',true);
select set_config('c67.preview',public.preview_trip_change(current_setting('c67.trip')::uuid,1,'{"title":"Edited"}')->>'preview_id',true);
select set_config('c67.changed',public.apply_trip_change(current_setting('c67.preview')::uuid,'51111111-1111-4111-8111-111111111112')::text,true);
select is(current_setting('c67.changed')::jsonb->>'revision','2','Edit increments revision exactly once');
select is(public.apply_trip_change(current_setting('c67.preview')::uuid,'51111111-1111-4111-8111-111111111112'),current_setting('c67.changed')::jsonb,'Apply receipt is immutable');
select is(public.create_trip_v3('91111111-1111-4111-8111-111111111111','2026-11-01T02:00Z','UTC','unspecified','51111111-1111-4111-8111-111111111111'),current_setting('c67.original')::jsonb,'Create receipt survives later edits');
select throws_ok($$select public.preview_trip_change(current_setting('c67.trip')::uuid,1,'{"title":"Stale"}')$$,'PT409','Trip revision changed','Stale revision rejected');
select throws_ok($$select public.preview_trip_change(current_setting('c67.trip')::uuid,2,'{"owner_id":"forged"}')$$,'PT400','Invalid trip patch','Unsupported owner field rejected');
select throws_ok($$select public.preview_trip_change(current_setting('c67.trip')::uuid,2,'{"stop_order":["aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa"]}')$$,'PT400','Order must contain distinct existing trip occurrences','Foreign occurrence cannot enter reorder');
select set_config('c67.merge',public.preview_trip_change(current_setting('c67.trip')::uuid,2,'{"append_version_id":"91111111-1111-4111-8111-111111111112"}')->>'preview_id',true);
select set_config('c67.merged',public.apply_trip_change(current_setting('c67.merge')::uuid,'51111111-1111-4111-8111-111111111113')::text,true);
select is(jsonb_array_length(current_setting('c67.merged')::jsonb->'stops'),4,'Explicit append keeps both repeated-place occurrences');
select is(jsonb_array_length(current_setting('c67.merged')::jsonb->'sources'),2,'Append retains both source credits');
select ok(not exists(select 1 from public.trip_legs where trip_id=current_setting('c67.trip')::uuid and duration_seconds is not null),'Merge discards stale route estimates');
select throws_ok($$select public.claim_journal_job()$$,'42501','permission denied for function claim_journal_job','Traveller cannot claim media jobs');
select throws_ok($$select public.finish_journal_job(gen_random_uuid(),gen_random_uuid(),'{}')$$,'42501','permission denied for function finish_journal_job','Traveller cannot forge image validation');
select throws_ok($$select public.begin_journal_upload(current_setting('c67.trip')::uuid,(current_setting('c67.original')::jsonb->'stops'->0->>'id')::uuid,gen_random_uuid(),'image/png','{}')$$,'PT409','Stop location is unresolved','Unlocated legacy stop cannot claim presence');
select is(public.list_trip_album(current_setting('c67.trip')::uuid),'[]'::jsonb,'Private album starts empty');
select throws_ok($$select * from public.journal_uploads$$,'42501','permission denied for table journal_uploads','Session internals not exposed via table API');
select set_config('request.jwt.claim.sub','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',true);
select throws_ok($$select public.preview_trip_change(current_setting('c67.trip')::uuid,3,'{"title":"Forged"}')$$,'PT404','Trip not found','Other owner cannot preview edit');
select throws_ok($$select public.apply_trip_change(current_setting('c67.preview')::uuid,gen_random_uuid())$$,'PT404','Preview not found','Other owner cannot apply preview');
select throws_ok($$select public.list_trip_album(current_setting('c67.trip')::uuid)$$,'PT404','Trip not found','Other owner cannot list album');
reset role;
select ok(not (select public from storage.buckets where id='c67-journal-raw'),'Raw bucket stays private');
select ok(not (select public from storage.buckets where id='c67-journal-ready'),'Ready bucket stays private');
select is((select file_size_limit::integer from storage.buckets where id='c67-journal-raw'),5242880,'Storage ingress enforces byte cap');
select is((select count(*)::integer from public.journal_entries),0,'Rejected requests create no journals');
select * from finish();
rollback;
